def sha16_arquivo(p_):
    """o sha16 dos bytes do arquivo, lido na hora (nunca digitado)."""
    return __import__("hashlib").sha256(open(p_, "rb").read()).hexdigest()[:16]




def _stone(key, name, nome_op, origem_dir, flag_prefix, theorem, key_theorem, support, citados_fora, hip_enunciado, autoria):
    mod = "TGLExt." + name; ns = mod + "."; rel = "TGLExt/" + name + ".lean"
    contract = list(_DET[key]["teoremas"])
    assert theorem in contract and key_theorem in contract, (name, theorem, key_theorem)
    return {"key": key, "name": name, "mod": mod, "rel": rel, "ns": ns, "nome_do_operador": nome_op,
            "origem": os.path.join(origem_dir, name + ".lean"), "compilado_em": SANDBOX, "src": os.path.join(_P, name + ".lean"), "insumo": name + ".lean",
            "sha16_da_ordem": _PINS[key], "flag_prefix": flag_prefix, "grupo": key,
            "theorem": theorem, "key_theorem": key_theorem, "contract": contract, "support": dict(support), "citados_fora": dict(citados_fora), "auxiliares_fora_da_composicao": [],
            "hipoteses_no_enunciado": hip_enunciado, "autoria": autoria}


