def _sem_excluidas(lista_):
    """tira da lista as falas de VERBATIM_EXCLUIDAS_V405, pelo sha16 dos bytes do arquivo."""
    def _h(p_):   # (numa arvore emulada o ensaio original pode nao estar no caminho relativo: a lista que vale ali e' a congelada, abaixo)
        return __import__("hashlib").sha256(open(p_, "rb").read()).hexdigest()[:16] if os.path.exists(p_) else None
    return [p_ for p_ in lista_ if _h(p_) not in VERBATIM_EXCLUIDAS_V405]


