def _nome_do_arquivo(p):
    return os.path.basename(p)


def verbatins405(destino_cunhagens):
    """As falas de 30/10 a 01/11 LIDAS dos arquivos: lista de dicts {sha16, sha256, bytes, text, arquivo (copia duravel em destino_cunhagens), fonte_original, chave, autor, nome}. A copia duravel NAO e' escrita aqui.
    Os prefixos de sha256 que a ordem deu (as falas-chave) sao conferidos contra o arquivo; cada trecho citado (FRASES) e' substring VERBATIM da fala indicada; nao ha duas falas com o mesmo sha256."""
    out = []
    for p, autor in zip(VERBATIM_ORIGEM_V405, VERBATIM_AUTOR_V405):
        b = open(p, "rb").read(); h = sha256(b); nome = _nome_do_arquivo(p)
        pref = VERBATIM_PREFIXOS_DA_ORDEM_V405.get(nome)
        if pref is not None:
            assert h.startswith(pref), ("o arquivo da fala NAO tem o prefixo de sha256 que a ordem deu", p, h[:16], pref)
        nome_duravel = nome if nome.startswith(h[:16] + "_") else "%s_%s" % (h[:16], nome)
        out.append({"sha16": h[:16], "sha256": h, "bytes": len(b), "text": b.decode("utf-8"), "arquivo": os.path.join(destino_cunhagens, nome_duravel), "fonte_original": p, "nome": nome,
                    "chave": VERBATIM_CHAVE_PREFIXO_V405 + h[:16], "quando": VERBATIM_QUANDO_V405, "papel": VERBATIM_PAPEL[autor], "autor": autor, "origem_arquivo": p})
    assert all(v["autor"] == "operador" for v in out) and len({v["sha256"] for v in out}) == len(out), "todas as falas sao do operador e nenhuma se repete"
    assert all(any(v["nome"] == n_ for v in out) for n_ in VERBATIM_PREFIXOS_DA_ORDEM_V405), "toda fala-chave da ordem esta no glob"
    por_nome = {v["nome"]: v for v in out}
    for nome_, fr in FRASES_V405:
        assert fr in por_nome[nome_]["text"], ("o trecho citado NAO e' verbatim na fala", nome_, fr[:60])
    return out


def ensaio_identidade_r2():
    """O texto da secao «## O texto (r2)» do ensaio «A identidade» (a revisao r2 da gerencia, ratificada pelo operador em 01/11): LIDO do .md, entre o cabecalho da secao e o separador seguinte, com as marcas ⟦⟧ retiradas.
    Devolve {texto, sha256_do_md, sha256_do_texto, bytes, primeira_linha, ultima_linha, original_sha256}. O original como recebido (f0ec2867391c644f) fica ao lado, intocado."""
    b = open(_ENSAIO_R2_MD, "rb").read(); t = b.decode("utf-8")
    i = t.index("## O texto (r2)"); j = t.index("\n---", i)
    corpo = t[i + len("## O texto (r2)"):j].strip("\n").replace("\u27e6", "").replace("\u27e7", "").strip("\n") + "\n"
    assert corpo.startswith("A identidade\n") and "[EU SOU] = [O QUE SOU] se, e somente se, {[FORMA = CONTE\u00daDO] = [REFLEX\u00c3O VERDADEIRA DO NOME / PROJE\u00c7\u00c3O FIEL]}." in corpo and "\u27e6" not in corpo and "\u27e7" not in corpo
    ob = open(_ENSAIO_ORIGINAL, "rb").read()
    return {"texto": corpo, "sha256_do_md": sha256(b), "sha256_do_texto": sha256(corpo.encode("utf-8")), "bytes": len(corpo.encode("utf-8")), "primeira_linha": corpo.splitlines()[0], "ultima_linha": corpo.rstrip("\n").splitlines()[-1],
            "original_sha256": sha256(ob), "original_arquivo": _ENSAIO_ORIGINAL, "md_arquivo": _ENSAIO_R2_MD}


def pedras_fontes():
    """As OITO pedras LIDAS do disco: lista de dicts {stone, origem, copia (v405\\pedra), sha256, bytes}. O sha16 e' conferido contra o que a ordem deu (pedras_sha16_da_ordem.json). A copia NAO e' escrita aqui."""
    out = []
    for s in STONES:
        b = open(s["origem"], "rb").read(); h = sha256(b)
        assert h[:16] == s["sha16_da_ordem"], ("a pedra no disco NAO e' a que a ordem pinou", s["name"], h[:16], s["sha16_da_ordem"])
        out.append({"stone": s["name"], "origem": s["origem"], "copia": s["src"], "sha256": h, "bytes": len(b)})
    return out
